-- Extend the existing guarded reports; do not create achievements or permissions.
create or replace function private.development_learner_report(p_learner text,p_cohort text default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;
begin
 if auth.uid() is null then raise insufficient_privilege using message='Sign in is required.';end if;
 if p_learner is distinct from private.current_app_user_id() and (p_cohort is null or not private.has_staff_role('FACILITATOR') or not exists(select 1 from public.pilot_cohorts pc join public.cohort_members m on m.cohort_id=pc.id where pc.id=p_cohort and pc.status='ACTIVE' and lower(pc.facilitator_email)=private.current_email() and m.learner_user_id=p_learner and m.status='ACTIVE')) then raise insufficient_privilege using message='This learner is not assigned to you.';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',r.review_id,'competencyId',r.competency_id,'stage',r.stage,'at',r.at,'comparisonKey',r.comparison_key,'authorityId',r.contract_id,'reviewStatus','REVIEWED','sourceNature',r.source_nature,'labCode',r.lab_code,'context',r.context,'independent',r.independent,'followUpDays',r.follow_up_days,'perceptionLevel',r.perception_level,
 'taskTitle',c.title,'evidencePhase',case when not exists(select 1 from public.curriculum_evidence_mappings m where m.id=any(c.mapping_ids) and m.evidence_class<>'BASELINE') then 'BASELINE' else 'DEVELOPMENT' end,
 'practiceOptions',(select coalesce(jsonb_agg(jsonb_build_object('title',n.title,'labCode',n.lab_code,'ceiling',n.stage_ceiling,'comparisonKey',n.comparison_key) order by n.title),'[]'::jsonb) from public.development_task_contracts n where n.competency_id=r.competency_id and n.comparison_key=r.comparison_key and private.development_contract_is_current(n.id) and private.development_stage_level(n.stage_ceiling)>private.development_stage_level(r.stage)
 and exists(select 1 from public.lab_enrollments le where le.user_id=p_learner and le.lab_code=n.lab_code and le.lab_version=n.lab_version and le.status in ('IN_PROGRESS','EVIDENCE_REVIEW','COMPLETED'))
 and (p_learner=private.current_app_user_id() or exists(select 1 from public.pilot_cohorts pc where pc.id=p_cohort and pc.lab_code=n.lab_code and pc.lab_version=n.lab_version)))) order by r.at,r.review_id),'[]'::jsonb) into result
 from private.current_development_reviews() r join public.development_task_contracts c on c.id=r.contract_id where r.user_id=p_learner and (p_learner=private.current_app_user_id() or r.cohort_id=p_cohort);
 return result;
end $$;

create or replace function private.development_contract_workspace(p_cohort text default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare contracts jsonb; coverage jsonb;
begin
 if auth.uid() is null then raise insufficient_privilege using message='Sign in is required.';end if;
 if not private.has_staff_role('SYSTEM_ADMIN') and (p_cohort is null or not private.has_staff_role('FACILITATOR') or not exists(select 1 from public.pilot_cohorts c where c.id=p_cohort and c.status='ACTIVE' and lower(c.facilitator_email)=private.current_email())) then raise insufficient_privilege using message='Source or facilitator access is required.';end if;
 select coalesce(jsonb_agg(to_jsonb(c)),'[]'::jsonb) into contracts from public.development_task_contracts c where private.development_contract_is_current(c.id) and (p_cohort is null or exists(select 1 from public.pilot_cohorts pc where pc.id=p_cohort and pc.lab_code=c.lab_code and pc.lab_version=c.lab_version));
 with registry as(select distinct on(q.lab_code,q.lab_version,q.semantic_field_id) q.* from public.question_analysis_registry q where p_cohort is null or exists(select 1 from public.pilot_cohorts c where c.id=p_cohort and c.lab_code=q.lab_code and c.lab_version=q.lab_version) order by q.lab_code,q.lab_version,q.semantic_field_id,q.updated_at desc,q.id desc),
 versions as(select lab_code,lab_version,count(*) filter(where status<>'RETIRED') as registered_fields from registry group by lab_code,lab_version)
 select coalesce(jsonb_agg(jsonb_build_object('labCode',v.lab_code,'labVersion',v.lab_version,'registeredFields',v.registered_fields,
 'approvedFields',(select count(distinct m.semantic_field_id) from public.curriculum_evidence_mappings m join registry r on r.id=m.registry_id where m.lab_code=v.lab_code and m.lab_version=v.lab_version and m.classification_status='APPROVED' and r.status<>'RETIRED' and m.id=(select x.id from public.curriculum_evidence_mappings x where x.lab_code=m.lab_code and x.lab_version=m.lab_version and x.semantic_field_id=m.semantic_field_id order by x.created_at desc,x.id desc limit 1)),
 'baselineContracts',(select count(*) from public.development_task_contracts c where c.lab_code=v.lab_code and c.lab_version=v.lab_version and private.development_contract_is_current(c.id) and not exists(select 1 from public.curriculum_evidence_mappings m where m.id=any(c.mapping_ids) and m.evidence_class<>'BASELINE')),
 'applicationContracts',(select count(*) from public.development_task_contracts c where c.lab_code=v.lab_code and c.lab_version=v.lab_version and private.development_contract_is_current(c.id) and c.source_nature='ASSESSED_TASK' and private.development_stage_level(c.stage_ceiling)>=3),
 'transferContracts',(select count(*) from public.development_task_contracts c where c.lab_code=v.lab_code and c.lab_version=v.lab_version and private.development_contract_is_current(c.id) and c.source_nature='ASSESSED_TASK' and c.stage_ceiling='TRANSFER')) order by v.lab_code,v.lab_version),'[]'::jsonb) into coverage from versions v;
 return jsonb_build_object('contracts',contracts,'coverage',coverage,'boundary','Source coverage is not validation, learner attainment or evidence of programme effectiveness.');
end $$;

create or replace function private.development_safe_partition(p jsonb,n integer) returns jsonb
language sql immutable set search_path='' as $$
 select case when jsonb_typeof(p)='array' and (select sum((x->>'count')::integer) from jsonb_array_elements(p) x)=n and not exists(select 1 from jsonb_array_elements(p) x where (x->>'count')::integer<0 or (x->>'count')::integer between 1 and 2) then p else null end;
$$;
revoke all on function private.development_safe_partition(jsonb,integer) from public,anon,authenticated;

create or replace function private.development_programme_report(p_cohort text) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare population integer; rows jsonb;
begin
 if auth.uid() is null or not private.can_view_competency_cohort(p_cohort) then raise insufficient_privilege using message='Programme access is required.';end if;
 select count(distinct cm.learner_user_id)::integer into population from public.cohort_members cm join public.learners l on l.user_id=cm.learner_user_id and l.status='ACTIVE' join public.pilot_cohorts pc on pc.id=cm.cohort_id and pc.status='ACTIVE'
 where cm.cohort_id=p_cohort and cm.status='ACTIVE' and (select status from public.consent_records cr where cr.user_id=cm.learner_user_id and cr.consent_type='LEARNER_PRODUCT' order by cr.created_at desc,cr.id desc limit 1)='GRANTED';
 if population<5 then return jsonb_build_object('cohortId',p_cohort,'participantCount',population,'suppressed',true,'competencies','[]'::jsonb);end if;
 with facts as(select * from private.current_development_reviews() where cohort_id=p_cohort and reporting_allowed),
 current_fact as(select distinct on(user_id,competency_id) * from facts order by user_id,competency_id,at desc,review_id desc),
 person as(select f.*,b.stage as baseline_stage,b.at as baseline_at,a.perception_level as first_perception,a.stage as first_alignment_stage,a.at as first_alignment_at,
  (select bool_and(x.source_nature='ASSESSED_TASK') from facts x where x.user_id=f.user_id and x.competency_id=f.competency_id and x.comparison_key=f.comparison_key) as assessed_only,
  (select count(*) from facts x where x.user_id=f.user_id and x.competency_id=f.competency_id and x.comparison_key=f.comparison_key) as reviews,
  (select count(distinct x.at::date) from facts x where x.user_id=f.user_id and x.competency_id=f.competency_id and x.comparison_key=f.comparison_key and x.independent and private.development_stage_level(x.stage)>=3) as independent_days,
  exists(select 1 from facts x where x.user_id=f.user_id and x.competency_id=f.competency_id and x.comparison_key=f.comparison_key and x.stage='TRANSFER') as has_transfer,
  exists(select 1 from facts x where x.user_id=f.user_id and x.competency_id=f.competency_id and x.comparison_key=f.comparison_key and x.independent and private.development_stage_level(x.stage)>=3 and f.follow_up_days is not null and x.at>=(select min(ap.at) from facts ap where ap.user_id=f.user_id and ap.competency_id=f.competency_id and ap.comparison_key=f.comparison_key and ap.independent and private.development_stage_level(ap.stage)>=3)+f.follow_up_days*interval '1 day') as has_followup
 from current_fact f join lateral(select * from facts x where x.user_id=f.user_id and x.competency_id=f.competency_id and x.comparison_key=f.comparison_key order by x.at,x.review_id limit 1) b on true left join lateral(select x.perception_level,x.stage,x.at from facts x where x.user_id=f.user_id and x.competency_id=f.competency_id and x.comparison_key=f.comparison_key and x.perception_level is not null order by x.at,x.review_id limit 1) a on true),
 partitions as(
 select competency_id,'distribution' as kind,stage as code,count(*)::integer as n from person group by competency_id,stage
 union all select competency_id,'baselineDistribution',baseline_stage,count(*)::integer from person group by competency_id,baseline_stage
 union all select competency_id,'changeDistribution',case when baseline_at>=at then 'INSUFFICIENT_HISTORY' when private.development_stage_level(stage)>private.development_stage_level(baseline_stage) then 'HIGHER_REVIEWED_STAGE' when private.development_stage_level(stage)<private.development_stage_level(baseline_stage) then 'LOWER_REVIEWED_STAGE' else 'SAME_REVIEWED_STAGE' end,count(*)::integer from person group by competency_id,3
 union all select competency_id,'strengthDistribution',case when assessed_only and reviews>=3 and independent_days>=3 then 'STRONG' when reviews>=2 then 'MODERATE' else 'LIMITED' end,count(*)::integer from person group by competency_id,3
 union all select competency_id,'sourceDistribution',case when assessed_only then 'ASSESSED_TASK' else 'SELF_REPORT' end,count(*)::integer from person group by competency_id,3
 union all select competency_id,'alignmentDistribution',case when perception_level is null then 'NO_COMPATIBLE_COMPARISON' when abs(perception_level-private.development_stage_level(stage))=0 then 'SAME_STAGE' when abs(perception_level-private.development_stage_level(stage))=1 then 'ONE_STAGE_APART' else 'TWO_OR_MORE_STAGES_APART' end,count(*)::integer from person group by competency_id,3
 union all select competency_id,'alignmentChangeDistribution',case when first_alignment_at>=at or perception_level is null or first_perception is null then 'NO_COMPATIBLE_PAIR' when abs(perception_level-private.development_stage_level(stage))<abs(first_perception-private.development_stage_level(first_alignment_stage)) then 'SMALLER_GAP' when abs(perception_level-private.development_stage_level(stage))>abs(first_perception-private.development_stage_level(first_alignment_stage)) then 'LARGER_GAP' else 'SAME_GAP' end,count(*)::integer from person group by competency_id,3
 union all select competency_id,kind,case when kind in ('distribution','baselineDistribution') then 'NOT_YET_EVIDENCED' when kind='alignmentDistribution' then 'NO_COMPATIBLE_COMPARISON' when kind='alignmentChangeDistribution' then 'NO_COMPATIBLE_PAIR' else 'NO_REVIEWED_EVIDENCE' end,population-count(*)::integer from person cross join unnest(array['distribution','baselineDistribution','changeDistribution','strengthDistribution','sourceDistribution','alignmentDistribution','alignmentChangeDistribution']) kind group by competency_id,kind),
 partition_values as(select competency_id,kind,private.development_safe_partition(jsonb_agg(jsonb_build_object('code',code,'count',n) order by code),population) as value from(select competency_id,kind,code,sum(n)::integer n from partitions group by competency_id,kind,code) p group by competency_id,kind),
 totals as(select competency_id,count(*)::integer as covered,sum(reviews)::integer as evidence_count,count(*) filter(where has_transfer)::integer as transferred,count(*) filter(where independent_days>=3)::integer as repeated,count(*) filter(where has_followup)::integer as followup,count(*) filter(where perception_level is not null)::integer as alignment,count(*) filter(where assessed_only and baseline_at<at and private.development_stage_level(stage)>private.development_stage_level(baseline_stage))::integer as assessed_growth from person group by competency_id),
 calendar as(select g as period from public.pilot_cohorts c cross join lateral generate_series(greatest(date_trunc('month',coalesce(c.starts_on::timestamptz,now()-interval '11 months')),date_trunc('month',now()-interval '11 months')),date_trunc('month',least(coalesce(c.ends_on::timestamptz,now()),now())),interval '1 month') g where c.id=p_cohort),
 snapshots as(select t.competency_id,calendar.period,(select count(*)::integer from (select distinct on(x.user_id) x.stage,x.source_nature from facts x where x.competency_id=t.competency_id and x.at<calendar.period+interval '1 month' order by x.user_id,x.at desc,x.review_id desc) latest where latest.source_nature='ASSESSED_TASK' and private.development_stage_level(latest.stage)>=3) as applied from totals t cross join calendar),
 safe as(select t.* from totals t where not exists(select 1 from partition_values p where p.competency_id=t.competency_id and p.kind in ('distribution','changeDistribution','strengthDistribution') and p.value is null) and not exists(select 1 from unnest(array[t.covered,population-t.covered,t.transferred,population-t.transferred,t.repeated,population-t.repeated,t.followup,population-t.followup,t.alignment,population-t.alignment]) n where n between 1 and 2))
 select coalesce(jsonb_agg(jsonb_build_object('competencyId',t.competency_id,'distribution',(select value from partition_values p where p.competency_id=t.competency_id and kind='distribution'),'changeDistribution',(select value from partition_values p where p.competency_id=t.competency_id and kind='changeDistribution'),'strengthDistribution',(select value from partition_values p where p.competency_id=t.competency_id and kind='strengthDistribution'),'baselineDistribution',(select value from partition_values p where p.competency_id=t.competency_id and kind='baselineDistribution'),'sourceDistribution',(select value from partition_values p where p.competency_id=t.competency_id and kind='sourceDistribution'),'alignmentDistribution',(select value from partition_values p where p.competency_id=t.competency_id and kind='alignmentDistribution'),'alignmentChangeDistribution',(select value from partition_values p where p.competency_id=t.competency_id and kind='alignmentChangeDistribution'),'transferParticipants',t.transferred,'repeatedApplicationParticipants',t.repeated,'followupParticipants',t.followup,'alignmentParticipants',t.alignment,'evidenceCount',t.evidence_count,'assessedGrowthParticipants',case when t.assessed_growth between 1 and 2 or population-t.assessed_growth between 1 and 2 then null else t.assessed_growth end,'trajectory',(select coalesce(jsonb_agg(jsonb_build_object('period',to_char(s.period,'YYYY-MM'),'assessedApplicationParticipants',case when s.applied between 1 and 2 or population-s.applied between 1 and 2 then null else s.applied end) order by s.period),'[]'::jsonb) from snapshots s where s.competency_id=t.competency_id)) order by t.competency_id),'[]'::jsonb) into rows from safe t;
 return jsonb_build_object('cohortId',p_cohort,'participantCount',population,'suppressed',false,'competencies',rows,'assessmentCount',(select case when count(distinct r.review_id)>=3 then count(distinct r.review_id) else null end from private.current_development_reviews() r where r.cohort_id=p_cohort and r.reporting_allowed and exists(select 1 from jsonb_array_elements(rows) a where a->>'competencyId'=r.competency_id)));
end $$;
